        ("synthetic-account-07", "synthetic-strategy-07", "2025-01-01", None),
        ("synthetic-account-08", "synthetic-strategy-08", "2025-01-01", None),
        ("synthetic-account-09", "synthetic-strategy-09", "2025-01-01", None),
