    assert report["schema_version"] == 3
    assert report["numeric_verification"] == {
        "candidate_count": 1,
        "comparison_count": 1,
        "discrepancy_count": 0,
        "disposition": "INDEPENDENT_RECALCULATION_NO_DISCREPANCIES",
    }


