def test_t2_fact_projections_carry_each_funded_epoch_pre_start_observation(
    perimeter_module: Any, verifier_module: Any
) -> None:
    """R1 needs the S-1 valuation in the calculation ledger (builder and verifier).

    Pre-change both projections kept only in-window NAVs, so every funded
    epoch silently opened at the end of day S.
    """

    navs = [
        {
            "record_id": f"{account}-{day}",
            "account_id": account,
            "as_of_date": day,
            "nav": {"currency": "USD", "status": "AVAILABLE", "value": "1"},
        }
        for account, day in (
            ("acct-t2", "2026-01-01"),
            ("acct-t2", "2026-01-04"),
            ("acct-t2", "2026-01-05"),
            ("acct-t2", "2026-01-06"),
            ("acct-other", "2026-01-04"),
        )
    ]
    assignment = {
        "account_id": "acct-t2",
        "strategy_id": "strategy-t2",
        "effective_start": "2026-01-05",
        "effective_end": None,
    }
    receipt = {"requested_start": "2026-01-05", "requested_end": "2026-01-06"}
    builder_navs = perimeter_module._mixed_admitted_fact_projection(
        funded_assignments=[assignment],
        routes=[{"assignment": assignment, "receipt": receipt}],
        navs=navs,
        flows=[],
        events=[],
        capital_anchors=[],
    )[0]
    verifier_navs = verifier_module._mixed_admitted_fact_projection(
        funded_assignments=[assignment],
        routes=[{"selected_assignment": assignment, "receipt": receipt}],
        navs=navs,
        flows=[],
        events=[],
        capital_anchors=[],
    )[0]
    expected = ["acct-t2-2026-01-04", "acct-t2-2026-01-05", "acct-t2-2026-01-06"]
    assert [nav["record_id"] for nav in builder_navs] == expected
    assert [nav["record_id"] for nav in verifier_navs] == expected


def test_independent_verifier_matches_the_producer_on_a_funded_end_tail(
    verifier_module: Any,
) -> None:
    """#539: the independent derivation reproduces the producer's tail credits."""

    from tools import account_strategy_manifest as producer_module

    navs = {
        "2026-01-01": Decimal("100"),
        "2026-01-02": Decimal("110"),
        "2026-01-03": Decimal("3.03"),
        "2026-01-04": Decimal("40.75"),
        "2026-01-05": Decimal("40.75"),
    }
    producer_row = producer_module.analyze_epoch(
        navs,
        {},
        {("2026-01-03", "2026-01-03"): Decimal("120")},
        {},
        {},
        None,
        "2026-01-01",
        None,
        funded_end="2026-01-02",
    )
    facts = verifier_module._IndependentEpochFacts(
        "liquidated-account",
        date(2026, 1, 1),
        date(2026, 1, 5),
        tuple(
            verifier_module._IndependentNavFact(
                date.fromisoformat(as_of_date), "USD", value
            )
            for as_of_date, value in navs.items()
        ),
        (
            verifier_module._IndependentFlowFact(
                date(2026, 1, 3),
                "EXTERNAL_OUT",
                "USD",
                Decimal("120"),
                date(2026, 1, 3),
            ),
        ),
        None,
        True,
        None,
        date(2026, 1, 2),
    )
    verifier_row = verifier_module._derive_first_available_nav_epoch(facts)
    for field in (
        "observation_linked_return",
        "performance_closed_on",
        "post_liquidation_credits",
        "post_liquidation_income",
        "gain",
        "end",
        "performance_flags",
    ):
        assert verifier_row[field] == producer_row[field], field
    assert [
        link["end_date"] for link in verifier_row["observation_trace"]["links"]
    ] == ["2026-01-02"]


def test_policy_funded_end_closes_the_epoch_end_to_end_and_the_verifier_agrees(
    perimeter_module: Any, verifier_module: Any
) -> None:
    """#539: a policy ``funded_end`` flows producer -> payloads -> independent verifier."""

    selected = _mixed_composer_selected_inputs(perimeter_module)
    policy = json.loads(selected.admission_policy.contents)
    funded = [row for row in policy["admissions"] if row["status"] == "FUNDED"]
    assert len(funded) == 1
    funded[0]["funded_end"] = "2026-01-31"
    values = _selected_input_kwargs(selected)
    values.update(
        {
            "receipt_authority": selected.receipt_authority,
            "admission_policy": InputSnapshot.from_bytes(
                "mixed admission with funded end", canonical_json_bytes(policy)
            ),
            "manifest_schema": selected.manifest_schema,
            "membership_census": selected.membership_census,
        }
    )
    closed_selected = perimeter_module.AccountManifestSelectedInputs(**values)

    payloads = perimeter_module.build_account_manifest_payloads(closed_selected)
    output = json.loads(payloads["outputs/account-strategy-manifest.json"])
    row = next(item for item in output["rows"] if item["status"] == "OK")
    assert row["performance_closed_on"] == "2026-01-31"
    assert [
        (credit["start_date"], credit["end_date"], credit["amount"])
        for credit in row["post_liquidation_credits"]
    ] == [("2026-01-31", "2026-02-01", "10")]
    assert row["post_liquidation_income"] == "10"
    assert [link["end_date"] for link in row["observation_trace"]["links"]] == [
        "2026-01-31"
    ]
    verifier_module.IndependentAccountManifestVerifier().verify(
        _mixed_verifier_inputs(verifier_module, closed_selected), payloads
    )

    # A verifier that is told a different funded end refuses the manifest.
    other = json.loads(closed_selected.admission_policy.contents)
    next(row for row in other["admissions"] if row["status"] == "FUNDED")[
        "funded_end"
    ] = "2026-01-30"
    values["admission_policy"] = InputSnapshot.from_bytes(
        "mixed admission, other funded end", canonical_json_bytes(other)
    )
    other_selected = perimeter_module.AccountManifestSelectedInputs(**values)
    with pytest.raises(Exception):
        verifier_module.IndependentAccountManifestVerifier().verify(
            _mixed_verifier_inputs(verifier_module, other_selected), payloads
        )


def test_closed_epoch_with_a_flat_tail_has_no_credits_and_still_verifies(
    verifier_module: Any,
) -> None:
    """A funded end followed by unchanged NAV closes the epoch with an empty credit list."""

    from tools import account_strategy_manifest as producer_module

    navs = {
        "2026-01-01": Decimal("100"),
        "2026-01-02": Decimal("110"),
        "2026-01-03": Decimal("110"),
        "2026-01-04": Decimal("110"),
    }
    row = producer_module.analyze_epoch(
        navs, {}, {}, {}, {}, None, "2026-01-01", None, funded_end="2026-01-02"
    )
    assert row is not None
    assert row["performance_closed_on"] == "2026-01-02"
    assert row["post_liquidation_credits"] == []
    assert row["post_liquidation_income"] == Decimal("0")
    facts = verifier_module._IndependentEpochFacts(
        "flat-account",
        date(2026, 1, 1),
        date(2026, 1, 4),
        tuple(
            verifier_module._IndependentNavFact(
                date.fromisoformat(as_of_date), "USD", value
            )
            for as_of_date, value in navs.items()
        ),
        (),
        None,
        True,
        None,
        date(2026, 1, 2),
    )
    expected = verifier_module._derive_first_available_nav_epoch(facts)
    assert expected["post_liquidation_credits"] == []
    projection = {
        key: json.loads(json.dumps(value, default=str))
        for key, value in expected.items()
    }
    assert projection["performance_closed_on"] == "2026-01-02"


def _selected_with_general_and_blocked_facts(module: Any) -> object:
    """One account per disposition: gap (blocked), predates, follows, never assigned."""
    selected = _mvp_audit_001_selected_with_unmatched_facts(
        module, include_nav=True, include_flow=False
    )
    baseline_payload = selected.baseline.json_object()
    baseline_payload["accounts"].extend(
        {
            "account_id": account_id,
            "base_currency": "USD",
            "provider": "SYNTHETIC",
            "role": "INVESTMENT",
        }
        for account_id in ("synthetic-pinned-20", "synthetic-pinned-21")
    )
    baseline_payload["assignments"].append(
        _assignment(
            "synthetic-pinned-20",
            "STRATEGY_MAPPED",
            "2025-03-01",
            "2025-12-31",
            "synthetic-strategy-20",
        )
    )
    ledger = selected.provider_ledger.json_object()
    for record_id, account_id, day in (
        ("general-nav-predates", "synthetic-pinned-20", "2025-02-01"),
        ("general-nav-follows", "synthetic-pinned-20", "2026-02-01"),
        ("general-nav-never-assigned", "synthetic-pinned-21", "2026-02-01"),
    ):
        ledger["nav_observations"].append(
            {
                "record_id": record_id,
                "account_id": account_id,
                "as_of_date": day,
                "nav": {"currency": "USD", "status": "AVAILABLE", "value": "5.00"},
            }
        )
    baseline_snapshot = InputSnapshot.from_bytes(
        "general disposition synthetic baseline", canonical_json_bytes(baseline_payload)
    )
    ledger_snapshot = InputSnapshot.from_bytes(
        "general disposition synthetic ledger", canonical_json_bytes(ledger)
    )
    values = _selected_input_kwargs(selected)
    values["baseline"] = baseline_snapshot
    values["baseline_manifest"] = _generation_manifest_snapshot(
        catalog=baseline_snapshot,
        catalog_artifact_id="normalized/portfolio-baseline.json",
        catalog_schema_name="portfolio-baseline-catalog",
        catalog_schema_version="1",
        as_of_date="2026-02-01",
    )
    values["provider_ledger"] = ledger_snapshot
    values["provider_ledger_manifest"] = _generation_manifest_snapshot(
        catalog=ledger_snapshot,
        catalog_artifact_id="normalized/provider-ledger.json",
        catalog_schema_name="provider-ledger-catalog",
        catalog_schema_version="1",
        as_of_date="2026-02-01",
    )
    return module.AccountManifestSelectedInputs(**values)


def test_facts_outside_every_strategy_interval_are_general_unless_in_a_gap(
    perimeter_module: Any, verifier_module: Any
) -> None:
    """Predating, following or never-assigned facts are explicit GENERAL; a gap stays blocked."""
    selected = _selected_with_general_and_blocked_facts(perimeter_module)
    payloads = perimeter_module.build_blocked_account_manifest_payloads(selected)
    perimeter = json.loads(payloads["authority/account-assignment-perimeter.json"])

    general = {
        fact["source_identity"]["record_id"]: fact
        for fact in perimeter["general_facts"]
    }
    assert {
        record_id: (fact["reason"], fact["disposition"], fact["status"])
        for record_id, fact in general.items()
    } == {
        "general-nav-predates": (
            "PREDATES_FIRST_STRATEGY_ASSIGNMENT",
            "GENERAL_OUT_OF_STRATEGY_PERIMETER",
            "GENERAL",
        ),
        "general-nav-follows": (
            "FOLLOWS_LAST_STRATEGY_ASSIGNMENT",
            "GENERAL_OUT_OF_STRATEGY_PERIMETER",
            "GENERAL",
        ),
        "general-nav-never-assigned": (
            "NO_STRATEGY_ASSIGNED_TO_ACCOUNT",
            "GENERAL_OUT_OF_STRATEGY_PERIMETER",
            "GENERAL",
        ),
    }
    assert perimeter["general_fact_count"] == 3
    # The fact in the gap between two strategy intervals of one account is the
    # only undisposed fact, so the perimeter still refuses a one-to-one verdict.
    assert [
        fact["source_identity"]["record_id"] for fact in perimeter["unassigned_facts"]
    ] == ["mvp-audit-unmatched-nav"]
    assert perimeter["unassigned_fact_count"] == 1
    assert perimeter["fact_bijection_status"] == "BLOCKED_UNASSIGNED_FACTS"
    # The independent verifier re-derives the same partition from the inputs.
    verifier_module.IndependentAccountManifestVerifier().verify(
        verifier_module.IndependentVerifierInputs(**_selected_input_kwargs(selected)),
        payloads,
    )


def test_strategy_assigned_account_with_an_undisposed_fact_fails_the_perimeter(
    perimeter_module: Any,
) -> None:
    """No strategy-assigned account may carry a fact that is neither owned nor GENERAL."""
    selected = _selected_with_general_and_blocked_facts(perimeter_module)
    payloads = perimeter_module.build_blocked_account_manifest_payloads(selected)
    perimeter = json.loads(payloads["authority/account-assignment-perimeter.json"])
    assigned = {
        row["account_id"]
        for row in perimeter["rows"]
        if row["strategy_mapping_disposition"] == "STRATEGY_MAPPED"
    }
    undisposed = [
        fact for fact in perimeter["unassigned_facts"] if fact["account_id"] in assigned
    ]
    assert undisposed, "the gap fact belongs to a strategy-assigned account"
    assert perimeter["fact_bijection_status"] == "BLOCKED_UNASSIGNED_FACTS"
    assert all(fact["status"] == "BLOCKED" for fact in undisposed)
    # GENERAL never covers a day inside a strategy interval of its account.
    for fact in perimeter["general_facts"]:
        for row in perimeter["rows"]:
            if (
                row["account_id"] == fact["account_id"]
                and row["strategy_mapping_disposition"] == "STRATEGY_MAPPED"
            ):
                inside = row["effective_start"] <= fact["fact_date"] and (
                    row["effective_end"] is None
                    or fact["fact_date"] <= row["effective_end"]
                )
                assert not inside
